func (r *OrderRepo) Save(ctx context.Context, o Order) error {
    return r.inTx(ctx, func(tx *sql.Tx) error {
        if _, err := tx.ExecContext(ctx,
            `DELETE FROM order_line WHERE order_id = $1`, o.ID); err != nil {
            return err
        }
        return insertLines(ctx, tx, o.ID, o.Lines)   // helper: one batch INSERT
    })
}
